import{_ as e,o as a,c as n,a2 as i}from"./chunks/framework.RycU2wFZ.js";const h=JSON.parse('{"title":"Five Trust Problems in Agent Payments","description":"","frontmatter":{},"headers":[],"relativePath":"learn/02-agent-payments/trust-problems.md","filePath":"learn/02-agent-payments/trust-problems.md","lastUpdated":1792595354000}'),r={name:"learn/02-agent-payments/trust-problems.md"};function o(s,t,d,l,c,u){return a(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="five-trust-problems-in-agent-payments" tabindex="-1">Five Trust Problems in Agent Payments <a class="header-anchor" href="#five-trust-problems-in-agent-payments" aria-label="Permalink to &quot;Five Trust Problems in Agent Payments&quot;">​</a></h1><p>Letting an agent spend money raises five questions: <strong>Who authorized it? How much may it spend? Who receives the money? What happens when something fails? Who is accountable?</strong> A payment protocol answers only part of this.</p><table tabindex="0"><thead><tr><th>Question</th><th>Failure if unanswered</th><th>Example control</th></tr></thead><tbody><tr><td>Who authorized?</td><td>Impersonation or self-granted permissions</td><td>Authenticate identity and keep policy outside the model</td></tr><tr><td>How much?</td><td>Hallucinations or loops drain funds</td><td>Per-transaction limits, rolling budgets, circuit breakers, atomic reservations</td></tr><tr><td>To whom?</td><td>Funds go to a malicious or incorrect recipient</td><td>Verify merchant, domain, network, asset, and recipient against trusted policy</td></tr><tr><td>What if it fails?</td><td>Retry causes duplicate payment, or service is not delivered</td><td>Explicit state machine, idempotency, reconciliation, and recovery</td></tr><tr><td>Who is accountable?</td><td>No way to investigate or assign responsibility</td><td>Append-only audit events, attributable credentials, and emergency disablement</td></tr></tbody></table><h2 id="authorization-and-identity" tabindex="-1">Authorization and identity <a class="header-anchor" href="#authorization-and-identity" aria-label="Permalink to &quot;Authorization and identity&quot;">​</a></h2><p>Prompt injection may try to convince an agent to increase a budget or pay an attacker. Do not expose policy changes as unrestricted model tools. Derive identity from authenticated credentials rather than trusting a caller-supplied <code>X-Agent-ID</code> header. Keep private keys outside model-visible context.</p><h2 id="amount-and-concurrency" tabindex="-1">Amount and concurrency <a class="header-anchor" href="#amount-and-concurrency" aria-label="Permalink to &quot;Amount and concurrency&quot;">​</a></h2><p>Per-call limits do not stop a large number of small charges. Use cumulative budgets and rate controls. Concurrent requests must reserve budget atomically; otherwise two requests can each observe the same remaining balance and jointly overspend it.</p><h2 id="recipient-validation" tabindex="-1">Recipient validation <a class="header-anchor" href="#recipient-validation" aria-label="Permalink to &quot;Recipient validation&quot;">​</a></h2><p>An approved display name alone is insufficient. Bind provider identity to trusted domains, payment addresses, networks, and assets as appropriate to the rail. Validate the amount and recipient in the signed authorization.</p><h2 id="failure-and-recovery" tabindex="-1">Failure and recovery <a class="header-anchor" href="#failure-and-recovery" aria-label="Permalink to &quot;Failure and recovery&quot;">​</a></h2><p>A timeout can leave settlement unknown. Do not treat it as failure and repeat the payment automatically. Track intent, settlement, and fulfillment separately; use idempotency and reconciliation to resume only the unfinished step.</p><h2 id="accountability" tabindex="-1">Accountability <a class="header-anchor" href="#accountability" aria-label="Permalink to &quot;Accountability&quot;">​</a></h2><p>Record who or what requested an action, which policy decision applied, and what happened afterward. Keep an audit trail useful for investigation while protecting secrets. Provide a way to disable an agent or revoke its credentials quickly.</p><p>The core principle is that an LLM may propose a payment but must not grant itself financial authority. Deterministic controls should evaluate the request independently.</p>',14)])])}const m=e(r,[["render",o]]);export{h as __pageData,m as default};
